1	//! The [`URL`] value type: parses once on construction, then hands out
2	//! components through accessors mirroring the C++ header.
3	
4	use super::ascii;
5	use super::numeric::{self, NO_PORT};
6	use super::split;
7	
8	/// A parsed URL.
9	///
10	/// Construction never fails; a string that carries no usable location simply
11	/// reports [`URL::is_valid`] as `false`.
12	///
13	/// ```
14	/// use url_parser::URL;
15	///
16	/// let url = URL::new("https://user:pass@example.com:8080/a/b?x=1#top");
17	/// assert_eq!(url.scheme(), "https");
18	/// assert_eq!(url.authority(), "user:pass@example.com:8080");
19	/// assert_eq!(url.port(), 8080);
20	/// assert_eq!(url.path(), "/a/b");
21	/// assert_eq!(url.query(), "x=1");
22	/// assert_eq!(url.fragment(), "top");
23	/// assert!(url.is_valid());
24	/// ```
25	#[derive(Debug, Clone, PartialEq, Eq)]
26	pub struct URL {
27	    scheme: String,
28	    authority: String,
29	    host: String,
30	    port: i32,
31	    path: String,
32	    query: String,
33	    fragment: String,
34	}
35	
36	impl URL {
37	    /// Parses `input`, mirroring the C++ `url_parser::URL` constructor.
38	    ///
39	    /// The delimiter order is fragment, then query, then scheme, then the
40	    /// authority/path split — see [`split`](super::split) for why that is
41	    /// observable.
42	    pub fn new(input: &str) -> Self {
43	        let (before_fragment, fragment) = split::split_fragment(input);
44	        let (before_query, query) = split::split_query(before_fragment);
45	
46	        let mut url = URL {
47	            scheme: String::new(),
48	            authority: String::new(),
49	            host: String::new(),
50	            port: NO_PORT,
51	            path: String::new(),
52	            query: query.to_string(),
53	            fragment: fragment.to_string(),
54	        };
55	
56	        match split::split_scheme(before_query) {
57	            // No `"://"`: everything left over is the path, and there is no
58	            // authority to speak of.
59	            None => url.path = before_query.to_string(),
60	            Some((scheme, after_scheme)) => {
61	                url.scheme = ascii::to_lower(scheme);
62	
63	                let (raw_authority, path) = split::split_authority_and_path(after_scheme);
64	                url.path = path.to_string();
65	
66	                let (userinfo, host_port) = split::split_userinfo(raw_authority);
67	                let (host, port_text) = split::split_host_port(host_port);
68	                url.host = host.to_string();
69	                if let Some(text) = port_text {
70	                    url.port = numeric::parse_port(text);
71	                }
72	                url.authority = rebuild_authority(userinfo, host, url.port);
73	            }
74	        }
75	
76	        url
77	    }
78	
79	    /// The lower-cased scheme, without the `"://"`; empty when absent.
80	    pub fn scheme(&self) -> &str {
81	        &self.scheme
82	    }
83	
84	    /// The authority as re-serialised from userinfo, host and port.
85	    ///
86	    /// This is *not* a slice of the input: an unusable port is dropped along
87	    /// with its colon, and a usable one is re-rendered in canonical decimal, so
88	    /// `"h:065"` comes back as `"h:65"` and `"h:abc"` as `"h"`.
89	    pub fn authority(&self) -> &str {
90	        &self.authority
91	    }
92	
93	    /// The port, or `-1` when none was written or the written one was unusable.
94	    pub fn port(&self) -> i32 {
95	        self.port
96	    }
97	
98	    /// The path, including its leading `'/'`; empty when absent.
99	    pub fn path(&self) -> &str {
100	        &self.path
101	    }
102	
103	    /// The query, without the leading `'?'`; empty when absent.
104	    pub fn query(&self) -> &str {
105	        &self.query
106	    }
107	
108	    /// The fragment, without the leading `'#'`; empty when absent.
109	    pub fn fragment(&self) -> &str {
110	        &self.fragment
111	    }
112	
113	    /// Whether the URL names something: a non-empty host or a non-empty path.
114	    ///
115	    /// A scheme, query or fragment on its own is not enough, so `"http://"`,
116	    /// `"http://?q"` and `"http://:80"` are all invalid while `"/"` is valid.
117	    pub fn is_valid(&self) -> bool {
118	        !self.host.is_empty() || !self.path.is_empty()
119	    }
120	}
121	
122	/// Re-renders the authority from its parsed pieces.
123	///
124	/// The `'@'` is emitted only for a non-empty userinfo, which is why `"@h:80"`
125	/// canonicalises to `"h:80"` while `"h:80@"` keeps its trailing `'@'`.
126	fn rebuild_authority(userinfo: &str, host: &str, port: i32) -> String {
127	    let mut authority = String::new();
128	    if !userinfo.is_empty() {
129	        authority.push_str(userinfo);
130	        authority.push('@');
131	    }
132	    authority.push_str(host);
133	    if port != NO_PORT {
134	        authority.push(':');
135	        authority.push_str(&port.to_string());
136	    }
137	    authority
138	}
