1	//! The delimiter scans that carve a URL into its components.
2	//!
3	//! Every function here is a pure lexical split returning borrowed byte slices,
4	//! in the same order the C++ constructor applies them. That order is observable:
5	//! because the fragment is removed before the scheme is looked for, a `"://"`
6	//! sitting inside a fragment or a query never produces a scheme.
7	
8	use super::bytes::{find_byte, find_pattern};
9	
10	/// Splits the fragment at the **first** `b'#'`, returning `(remainder, fragment)`.
11	///
12	/// Later `'#'` and `'?'` bytes stay inside the fragment.
13	pub fn split_fragment(input: &[u8]) -> (&[u8], &[u8]) {
14	    match find_byte(input, b'#') {
15	        Some(at) => (&input[..at], &input[at + 1..]),
16	        None => (input, b""),
17	    }
18	}
19	
20	/// Splits the query at the **first** `b'?'`, returning `(remainder, query)`.
21	///
22	/// Runs after [`split_fragment`], so it only ever sees the pre-fragment text.
23	pub fn split_query(input: &[u8]) -> (&[u8], &[u8]) {
24	    match find_byte(input, b'?') {
25	        Some(at) => (&input[..at], &input[at + 1..]),
26	        None => (input, b""),
27	    }
28	}
29	
30	/// Splits on the first `b"://"`, returning `(raw_scheme, remainder)`.
31	///
32	/// `None` when the separator is absent, which is what makes a bare
33	/// `"http:example.com"` parse as a path rather than a scheme. No grammar check
34	/// is applied to the scheme text: `"1http"`, `"ht tp"` and `"/a"` are all
35	/// accepted verbatim, exactly as the reference accepts them.
36	pub fn split_scheme(input: &[u8]) -> Option<(&[u8], &[u8])> {
37	    find_pattern(input, b"://").map(|at| (&input[..at], &input[at + 3..]))
38	}
39	
40	/// Splits the post-`"://"` text into `(raw_authority, path)` at the first `b'/'`.
41	///
42	/// The `'/'` itself belongs to the path, and an absent `'/'` yields an empty path
43	/// rather than an empty authority.
44	pub fn split_authority_and_path(input: &[u8]) -> (&[u8], &[u8]) {
45	    match find_byte(input, b'/') {
46	        Some(at) => (&input[..at], &input[at..]),
47	        None => (input, b""),
48	    }
49	}
50	
51	/// Splits the raw authority at the **first** `b'@'`, returning
52	/// `(userinfo, host_port)`.
53	///
54	/// First — not last — which is why `"a@b:80@c:90"` has userinfo `"a"` and
55	/// host/port text `"b:80@c:90"`, yielding port `80`.
56	pub fn split_userinfo(authority: &[u8]) -> (&[u8], &[u8]) {
57	    match find_byte(authority, b'@') {
58	        Some(at) => (&authority[..at], &authority[at + 1..]),
59	        None => (b"", authority),
60	    }
61	}
62	
63	/// Splits the host/port text at the **first** `b':'`, returning
64	/// `(host, port_text)`.
65	///
66	/// `port_text` is `None` only when there is no colon at all, distinguishing "no
67	/// port was written" from "a port was written but did not convert".
68	pub fn split_host_port(host_port: &[u8]) -> (&[u8], Option<&[u8]>) {
69	    match find_byte(host_port, b':') {
70	        Some(at) => (&host_port[..at], Some(&host_port[at + 1..])),
71	        None => (host_port, None),
72	    }
73	}
74	
75	#[cfg(test)]
76	mod tests {
77	    use super::*;
78	
79	    #[test]
80	    fn fragment_and_query_take_the_first_delimiter() {
81	        assert_eq!(split_fragment(b"a#b#c"), (&b"a"[..], &b"b#c"[..]));
82	        assert_eq!(split_fragment(b"a?b#c"), (&b"a?b"[..], &b"c"[..]));
83	        assert_eq!(split_query(b"a?b?c"), (&b"a"[..], &b"b?c"[..]));
84	        assert_eq!(split_query(b"no-query"), (&b"no-query"[..], &b""[..]));
85	    }
86	
87	    #[test]
88	    fn scheme_requires_the_full_separator() {
89	        assert_eq!(split_scheme(b"http://h"), Some((&b"http"[..], &b"h"[..])));
90	        assert_eq!(split_scheme(b"/a://b"), Some((&b"/a"[..], &b"b"[..])));
91	        assert_eq!(split_scheme(b"http:/h"), None);
92	        assert_eq!(split_scheme(b"http:h"), None);
93	    }
94	
95	    #[test]
96	    fn authority_stops_at_the_first_slash() {
97	        assert_eq!(split_authority_and_path(b"h/p/q"), (&b"h"[..], &b"/p/q"[..]));
98	        assert_eq!(split_authority_and_path(b"h"), (&b"h"[..], &b""[..]));
99	        assert_eq!(split_authority_and_path(b"/p"), (&b""[..], &b"/p"[..]));
100	    }
101	
102	    #[test]
103	    fn userinfo_and_port_use_first_delimiters() {
104	        assert_eq!(split_userinfo(b"a@b:80@c:90"), (&b"a"[..], &b"b:80@c:90"[..]));
105	        assert_eq!(split_userinfo(b"h:80@"), (&b"h:80"[..], &b""[..]));
106	        assert_eq!(split_userinfo(b"h:80"), (&b""[..], &b"h:80"[..]));
107	        assert_eq!(split_host_port(b"a:b:c"), (&b"a"[..], Some(&b"b:c"[..])));
108	        assert_eq!(split_host_port(b"h"), (&b"h"[..], None));
109	        assert_eq!(split_host_port(b"h:"), (&b"h"[..], Some(&b""[..])));
110	    }
111	}
