1	//! Emulation of `std::stoi` and the port-range check layered on top of it.
2	//!
3	//! `std::stoi` delegates to `strtol` with base 10 and then narrows to `int`,
4	//! which gives it three behaviours a naive `str::parse::<i32>()` does not have:
5	//!
6	//! * leading `"C"`-locale whitespace and a single optional sign are accepted;
7	//! * conversion stops at the first non-digit instead of failing, so `"80abc"`,
8	//!   `"80.5"` and `"0x50"` yield `80`, `80` and `0`;
9	//! * a missing digit sequence throws `invalid_argument`, and a value outside
10	//!   `int` range throws `out_of_range` — both surface here as `None`.
11	
12	use super::ascii;
13	
14	/// Largest magnitude we keep accumulating before latching the overflow flag.
15	///
16	/// Anything beyond this is already outside `int` range, so the exact value stops
17	/// mattering — we only need to keep consuming digits without wrapping the `i64`
18	/// accumulator, however many digits follow.
19	const OVERFLOW_GUARD: i64 = 1 << 32;
20	
21	/// Highest port the reference accepts; anything else collapses to [`NO_PORT`].
22	const MAX_PORT: i32 = 65535;
23	
24	/// Sentinel the C++ `port()` accessor returns when no usable port was found.
25	pub const NO_PORT: i32 = -1;
26	
27	/// Emulates `std::stoi(s)`, returning `None` where the C++ call would throw.
28	pub fn stoi(bytes: &[u8]) -> Option<i32> {
29	    let mut i = 0;
30	
31	    while i < bytes.len() && ascii::is_space(bytes[i]) {
32	        i += 1;
33	    }
34	
35	    let negative = match bytes.get(i) {
36	        Some(&b'-') => {
37	            i += 1;
38	            true
39	        }
40	        Some(&b'+') => {
41	            i += 1;
42	            false
43	        }
44	        _ => false,
45	    };
46	
47	    let first_digit = i;
48	    let mut magnitude: i64 = 0;
49	    let mut overflowed = false;
50	    while i < bytes.len() && bytes[i].is_ascii_digit() {
51	        if !overflowed {
52	            magnitude = magnitude * 10 + i64::from(bytes[i] - b'0');
53	            overflowed = magnitude > OVERFLOW_GUARD;
54	        }
55	        i += 1;
56	    }
57	
58	    // No digits at all: `std::stoi` throws `invalid_argument`.
59	    if i == first_digit {
60	        return None;
61	    }
62	    // Past `int` range: `std::stoi` throws `out_of_range`.
63	    if overflowed {
64	        return None;
65	    }
66	
67	    let value = if negative { -magnitude } else { magnitude };
68	    if value < i64::from(i32::MIN) || value > i64::from(i32::MAX) {
69	        return None;
70	    }
71	    Some(value as i32)
72	}
73	
74	/// Converts the text following the host's `':'` into a port number.
75	///
76	/// Values that fail conversion or fall outside `0..=65535` are reported as
77	/// [`NO_PORT`], which also suppresses the `":port"` suffix in the rebuilt
78	/// authority.
79	pub fn parse_port(bytes: &[u8]) -> i32 {
80	    match stoi(bytes) {
81	        Some(value) if (0..=MAX_PORT).contains(&value) => value,
82	        _ => NO_PORT,
83	    }
84	}
85	
86	#[cfg(test)]
87	mod tests {
88	    use super::*;
89	
90	    #[test]
91	    fn matches_strtol_prefix_semantics() {
92	        assert_eq!(stoi(b"80abc"), Some(80));
93	        assert_eq!(stoi(b"80.5"), Some(80));
94	        assert_eq!(stoi(b"0x50"), Some(0));
95	        assert_eq!(stoi(b"8 0"), Some(8));
96	        assert_eq!(stoi(b" \t\x0b\x0c\r\n+80"), Some(80));
97	        assert_eq!(stoi(b"065"), Some(65));
98	        assert_eq!(stoi(b"-0"), Some(0));
99	        assert_eq!(stoi(b"-2147483648"), Some(i32::MIN));
100	        assert_eq!(stoi(b"2147483647"), Some(i32::MAX));
101	    }
102	
103	    #[test]
104	    fn reports_throwing_cases_as_none() {
105	        assert_eq!(stoi(b""), None);
106	        assert_eq!(stoi(b" "), None);
107	        assert_eq!(stoi(b"abc"), None);
108	        assert_eq!(stoi(b"--80"), None);
109	        assert_eq!(stoi(b"+-80"), None);
110	        assert_eq!(stoi(b"\xf8"), None);
111	        assert_eq!(stoi(b"2147483648"), None);
112	        assert_eq!(stoi(b"-2147483649"), None);
113	    }
114	
115	    /// A digit run far longer than `i64` could hold must latch the overflow flag
116	    /// rather than wrap the accumulator.
117	    #[test]
118	    fn very_long_digit_runs_do_not_wrap() {
119	        assert_eq!(stoi(&[b'9'; 40]), None);
120	        assert_eq!(stoi(&[b'0'; 40]), Some(0));
121	        let mut padded = vec![b'0'; 40];
122	        padded.push(b'8');
123	        padded.push(b'0');
124	        assert_eq!(stoi(&padded), Some(80));
125	    }
126	
127	    #[test]
128	    fn parse_port_clamps_to_valid_range() {
129	        assert_eq!(parse_port(b"0"), 0);
130	        assert_eq!(parse_port(b"65535"), 65535);
131	        assert_eq!(parse_port(b"65536"), NO_PORT);
132	        assert_eq!(parse_port(b"-80"), NO_PORT);
133	        assert_eq!(parse_port(b"abc"), NO_PORT);
134	    }
135	}
