1	//! Substring searches over byte slices.
2	//!
3	//! The parser works on bytes rather than `str` because C++ `std::string` is a
4	//! byte string: the reference implementation happily parses an argument that is
5	//! not valid UTF-8, and reproducing that requires never assuming an encoding.
6	//! `str::find` is therefore unavailable, so the two searches the parser needs
7	//! live here.
8	
9	/// Byte offset of the first occurrence of `needle` in `haystack`.
10	pub fn find_byte(haystack: &[u8], needle: u8) -> Option<usize> {
11	    haystack.iter().position(|&b| b == needle)
12	}
13	
14	/// Byte offset of the first occurrence of the (non-empty) `needle` slice.
15	pub fn find_pattern(haystack: &[u8], needle: &[u8]) -> Option<usize> {
16	    if needle.len() > haystack.len() {
17	        return None;
18	    }
19	    haystack
20	        .windows(needle.len())
21	        .position(|window| window == needle)
22	}
23	
24	#[cfg(test)]
25	mod tests {
26	    use super::*;
27	
28	    #[test]
29	    fn finds_first_occurrence_only() {
30	        assert_eq!(find_byte(b"a:b:c", b':'), Some(1));
31	        assert_eq!(find_byte(b"abc", b':'), None);
32	        assert_eq!(find_pattern(b"a://b://c", b"://"), Some(1));
33	        assert_eq!(find_pattern(b"a:/b", b"://"), None);
34	        assert_eq!(find_pattern(b"://", b"://"), Some(0));
35	        assert_eq!(find_pattern(b":/", b"://"), None);
36	    }
37	
38	    #[test]
39	    fn tolerates_non_utf8_bytes() {
40	        assert_eq!(find_byte(b"\xff\xfe:", b':'), Some(2));
41	        assert_eq!(find_pattern(b"\xf8://x", b"://"), Some(1));
42	    }
43	}
